def below_zero(operations: list[int]) -> bool:
    def check(i: int, balance: int) -> bool:
        if i == len(operations):
            return False
        new_balance: int = balance + operations[i]
        if new_balance < 0:
            return True
        return check(i + 1, new_balance)
    return check(0, 0)

def sum_from(values: list[float], i: int) -> float:
    if i == len(values):
        return 0.0
    return values[i] + sum_from(values, i + 1)


def sum_abs_dev_from(numbers: list[float], i: int, center: float) -> float:
    if i == len(numbers):
        return 0.0
    diff: float = numbers[i] - center
    abs_diff: float = diff if diff >= 0.0 else -diff
    return abs_diff + sum_abs_dev_from(numbers, i + 1, center)


def mean_absolute_deviation(numbers: list[float]) -> float:
    if len(numbers) == 0:
        return 0.0
    center: float = sum_from(numbers, 0) / len(numbers)
    total_deviation: float = sum_abs_dev_from(numbers, 0, center)
    return total_deviation / len(numbers)

