def parse_nested_parens(paren_string: str) -> list[int]:
    depths = []
    for group in paren_string.split():
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif char == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths

