def longest(strings: list[str]) -> str | None:
    if len(strings) == 0:
        return None

    def helper(index: int, best: str) -> str:
        if index == len(strings):
            return best
        candidate: str = strings[index]
        next_best: str = candidate if len(candidate) > len(best) else best
        return helper(index + 1, next_best)

    return helper(1, strings[0])

def greatest_common_divisor(a: int, b: int) -> int:
    """Return a greatest common divisor of two integers a and b."""
    if a < 0:
        return greatest_common_divisor(-a, b)
    if b < 0:
        return greatest_common_divisor(a, -b)
    if b == 0:
        return a
    return greatest_common_divisor(b, a % b)

def _prefix(string: str, length: int) -> str:
    if length == 0:
        return ""
    return _prefix(string, length - 1) + string[length - 1]


def all_prefixes(string: str) -> list[str]:
    return [_prefix(string, i) for i in range(1, len(string) + 1)]

