def matches_at(string: str, substring: str, i: int) -> bool:
    return len([j for j in range(0, len(substring)) if string[i + j] != substring[j]]) == 0


def how_many_times(string: str, substring: str) -> int:
    return len([i for i in range(0, len(string) - len(substring) + 1) if matches_at(string, substring, i)])

def min_from(numbers: list[float], idx: int, current: float) -> float:
    if idx == len(numbers):
        return current
    val: float = numbers[idx]
    next_current: float = val if val < current else current
    return min_from(numbers, idx + 1, next_current)


def max_from(numbers: list[float], idx: int, current: float) -> float:
    if idx == len(numbers):
        return current
    val: float = numbers[idx]
    next_current: float = val if val > current else current
    return max_from(numbers, idx + 1, next_current)


def rescale_to_unit(numbers: list[float]) -> list[float]:
    min_val: float = min_from(numbers, 1, numbers[0])
    max_val: float = max_from(numbers, 1, numbers[0])
    span: float = max_val - min_val
    return [(numbers[i] - min_val) / span for i in range(0, len(numbers))]

